import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r

def build(arr):
    if not arr or arr[0]=='n':
        return None
    r = T(int(arr[0]))
    q = deque([r]); i = 1
    while q and i < len(arr):
        n = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return r

def collect(node, out):
    if node is None: return
    out.append(node.v)
    collect(node.l, out)
    collect(node.r, out)

def min_diff_brute(root):
    vals = []
    collect(root, vals)
    n = len(vals)
    best = 10 ** 9
    for i in range(n):
        for j in range(i + 1, n):
            d = abs(vals[i] - vals[j])
            if d < best: best = d
    return best

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    root = build(data[1:1+n])
    print(min_diff_brute(root))

