            n.l = T(int(arr[i])); q.append(n.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            n.r = T(int(arr[i])); q.append(n.r)
        i += 1
    return r

def min_diff_best(root):
    best = 10 ** 9
    prev = None
    stack, cur = [], root
    while cur or stack:
        while cur:
            stack.append(cur); cur = cur.l
        cur = stack.pop()
        if prev is not None:
            d = cur.v - prev
            if d < best: best = d
        prev = cur.v
        cur = cur.r
    return best

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    root = build(data[1:1+n])
    print(min_diff_best(root))
